12	import org.springframework.http.MediaType;
13	import org.springframework.test.web.servlet.MockMvc;
14	import org.springframework.test.web.servlet.MvcResult;
15	
16	/**
17	 * HTTP 层错误语义与主流程：409 幂等冲突、422 业务拒绝、404 不存在、400 参数非法。
18	 */
19	@AutoConfigureMockMvc
20	class RadioApiTest extends IntegrationTestBase {
21	
22	    @Autowired
23	    private MockMvc mvc;
24	
25	    @Test
26	    void fullFlowOverHttp() throws Exception {
27	        long calibratorId = postAndGetId("/api/calibrators",
28	                "{\"code\":\"CAL-API-1\",\"name\":\"合成活度计\"}");
29	        // 日检恰 5% 通过
30	        mvc.perform(post("/api/calibrators/daily-check").contentType(MediaType.APPLICATION_JSON)
31	                        .content("{\"requestId\":\"REQ-CHK-1\",\"calibratorId\":" + calibratorId
32	                                + ",\"checkDate\":\"2026-09-26\",\"referenceActivityBq\":1000.0,"
33	                                + "\"measuredActivityBq\":1050.0}"))
34	                .andExpect(status().isOk())
35	                .andExpect(jsonPath("$.passed").value(true))
36	                .andExpect(jsonPath("$.deviationRatio").value(0.05));
37	        // 同键异参 → 409
38	        mvc.perform(post("/api/calibrators/daily-check").contentType(MediaType.APPLICATION_JSON)
39	                        .content("{\"requestId\":\"REQ-CHK-1\",\"calibratorId\":" + calibratorId
40	                                + ",\"checkDate\":\"2026-09-26\",\"referenceActivityBq\":1000.0,"
41	                                + "\"measuredActivityBq\":1060.0}"))
42	                .andExpect(status().isConflict());
43	
44	        long motherId = postAndGetId("/api/mother-liquors",
45	                "{\"batchCode\":\"ML-API-1\",\"nuclideCode\":\"SYN-1H\",\"initialActivityBq\":2200.0,"
46	                        + "\"referenceTime\":\"2026-09-26T00:00:00Z\"}");
47	        long prescriptionId = postAndGetId("/api/prescriptions",
48	                "{\"code\":\"RX-API-1\",\"nuclideCode\":\"SYN-1H\",\"prescribedActivityBq\":1000.0,"
49	                        + "\"administrationTime\":\"2026-09-26T01:00:00Z\"}");
50	
51	        // 分装恰 10% 合法，衰变推算至给药时刻恰 1100 Bq
52	        long dispensingId = postAndGetId("/api/dispensings/calculate",
53	                "{\"requestId\":\"REQ-CALC-1\",\"motherLiquorId\":" + motherId
54	                        + ",\"prescriptionId\":" + prescriptionId + ",\"calibratorId\":" + calibratorId + "}");
55	        mvc.perform(post("/api/dispensings/calculate").contentType(MediaType.APPLICATION_JSON)
56	                        .content("{\"requestId\":\"REQ-CALC-1\",\"motherLiquorId\":" + motherId
57	                                + ",\"prescriptionId\":" + prescriptionId + ",\"calibratorId\":" + calibratorId
58	                                + "}"))
59	                .andExpect(status().isOk())
60	                .andExpect(jsonPath("$.id").value(dispensingId))
61	                .andExpect(jsonPath("$.dispensedActivityBq").value(1100.0))
62	                .andExpect(jsonPath("$.deviationRatio").value(0.1))
63	                .andExpect(jsonPath("$.status").value("CALCULATED"));
64	
65	        // 未核对直接发药 → 422
66	        mvc.perform(post("/api/dispensings/dispense").contentType(MediaType.APPLICATION_JSON)
67	                        .content("{\"requestId\":\"REQ-DISP-0\",\"dispensingId\":" + dispensingId
68	                                + ",\"remainingActivityBq\":0.0,\"measuredAt\":\"2026-09-26T01:00:00Z\"}"))
69	                .andExpect(status().isUnprocessableEntity());
70	
71	        // 双人核对：同一人第二次 → 409
72	        mvc.perform(post("/api/dispensings/{id}/checks", dispensingId)
73	                        .contentType(MediaType.APPLICATION_JSON).content("{\"checker\":\"alice\"}"))
74	                .andExpect(status().isOk())
75	                .andExpect(jsonPath("$.firstChecker").value("alice"));
76	        mvc.perform(post("/api/dispensings/{id}/checks", dispensingId)
77	                        .contentType(MediaType.APPLICATION_JSON).content("{\"checker\":\"alice\"}"))
78	                .andExpect(status().isConflict());
79	        mvc.perform(post("/api/dispensings/{id}/checks", dispensingId)
80	                        .contentType(MediaType.APPLICATION_JSON).content("{\"checker\":\"bob\"}"))
81	                .andExpect(status().isOk())
82	                .andExpect(jsonPath("$.status").value("CHECKED"));
83	
84	        // 勾稽不平衡 → 422，库存不变
85	        mvc.perform(post("/api/dispensings/dispense").contentType(MediaType.APPLICATION_JSON)
86	                        .content("{\"requestId\":\"REQ-DISP-1\",\"dispensingId\":" + dispensingId
87	                                + ",\"remainingActivityBq\":500.0,\"measuredAt\":\"2026-09-26T01:00:00Z\"}"))
88	                .andExpect(status().isUnprocessableEntity());
89	
90	        // 勾稽平衡发药：2200 = 1100 + 0 + 1100
91	        mvc.perform(post("/api/dispensings/dispense").contentType(MediaType.APPLICATION_JSON)
92	                        .content("{\"requestId\":\"REQ-DISP-2\",\"dispensingId\":" + dispensingId
93	                                + ",\"remainingActivityBq\":0.0,\"measuredAt\":\"2026-09-26T01:00:00Z\"}"))
94	                .andExpect(status().isOk())
95	                .andExpect(jsonPath("$.status").value("DISPENSED"))
96	                .andExpect(jsonPath("$.replayed").value(false))
97	                .andExpect(jsonPath("$.ledger.balanced").value(true))
98	                .andExpect(jsonPath("$.ledger.decayResidualBq").value(1100.0));
99	        // 终态重复完成 → 幂等成功
100	        mvc.perform(post("/api/dispensings/dispense").contentType(MediaType.APPLICATION_JSON)
101	                        .content("{\"requestId\":\"REQ-DISP-2\",\"dispensingId\":" + dispensingId
102	                                + ",\"remainingActivityBq\":0.0,\"measuredAt\":\"2026-09-26T01:00:00Z\"}"))
103	                .andExpect(status().isOk())
104	                .andExpect(jsonPath("$.replayed").value(true));
105	        // 迟到测量数据只记迟到事件
106	        mvc.perform(post("/api/dispensings/{id}/measurements", dispensingId)
107	                        .contentType(MediaType.APPLICATION_JSON).content("{\"payload\":\"late=0.0\"}"))
108	                .andExpect(status().isOk())
109	                .andExpect(jsonPath("$.result").value("LATE_RECORDED"));
110	        // 台账复算
111	        mvc.perform(get("/api/dispensings/{id}/reconciliation", dispensingId))
112	                .andExpect(status().isOk())
113	                .andExpect(jsonPath("$.balanced").value(true))
114	                .andExpect(jsonPath("$.dispensedTotalBq").value(1100.0));
115	    }
116	
117	    @Test
118	    void notFoundAndBadRequestSemantics() throws Exception {
119	        mvc.perform(get("/api/dispensings/{id}", 999999))
120	                .andExpect(status().isNotFound());
121	        mvc.perform(post("/api/calibrators").contentType(MediaType.APPLICATION_JSON)
122	                        .content("{\"code\":\"\"}"))
123	                .andExpect(status().isBadRequest());
124	    }
125	
126	    private long postAndGetId(String url, String body) throws Exception {
127	        MvcResult result = mvc.perform(post(url).contentType(MediaType.APPLICATION_JSON).content(body))
128	                .andExpect(status().isOk())
129	                .andReturn();
130	        String json = result.getResponse().getContentAsString();
131	        return Long.parseLong(json.replaceAll(".*\"id\":(\\d+).*", "$1"));
132	    }
133	}
