14	 * 幂等：requestId 唯一，指纹覆盖 requestId 与全部业务字段；同键同参返回首次结果，同键异参 409。
15	 * 并发：同一活度计同一日仅允许一个校准会话，由 (calibrator_id, check_date) 唯一约束保证唯一受理。
16	 */
17	@Service
18	public class CalibratorService {
19	
20	    /** 日检合格阈值：相对偏差绝对值不超过 5%。 */
21	    public static final double QC_TOLERANCE = 0.05;
22	
23	    private final CalibratorRepository calibrators;
24	    private final Clock clock;
