31	    @Transactional
32	    public DailyCheck dailyCheck(String requestId, long calibratorId, LocalDate checkDate,
33	                                 double referenceActivityBq, double measuredActivityBq) {
34	        calibrators.findCalibratorById(calibratorId)
35	                .orElseThrow(() -> new NotFoundException("活度计不存在: " + calibratorId));
36	        String fingerprint = Fingerprints.of(requestId, calibratorId, checkDate,
37	                referenceActivityBq, measuredActivityBq);
38	
39	        var existing = calibrators.findDailyCheckByRequestId(requestId);
40	        if (existing.isPresent()) {
41	            return replayOrConflict(existing.get(), fingerprint);
42	        }
43	        calibrators.findDailyCheck(calibratorId, checkDate).ifPresent(other -> {
44	            throw new ConflictException("同一活度计当日已存在校准会话: calibratorId=" + calibratorId
45	                    + ", checkDate=" + checkDate);
46	        });
47	
48	        double deviation = (measuredActivityBq - referenceActivityBq) / referenceActivityBq;
49	        boolean passed = Math.abs(deviation) <= QC_TOLERANCE;
50	        DailyCheck check = new DailyCheck(0L, requestId, fingerprint, calibratorId, checkDate,
51	                referenceActivityBq, measuredActivityBq, deviation, passed);
52	        try {
53	            long id = calibrators.insertDailyCheck(check, clock.instant().getEpochSecond());
54	            return calibrators.findDailyCheckByRequestId(requestId)
55	                    .filter(c -> c.id() == id)
56	                    .orElseThrow(() -> new IllegalStateException("日检记录写入后读取失败"));
57	        } catch (DuplicateKeyException e) {
58	            // 并发受理：唯一约束保证只有一条落库，其余按幂等/冲突处理
59	            return calibrators.findDailyCheckByRequestId(requestId)
60	                    .map(c -> replayOrConflict(c, fingerprint))
61	                    .orElseThrow(() -> new ConflictException(
62	                            "同一活度计当日校准会话并发冲突: calibratorId=" + calibratorId));
63	        }
64	    }
65	
66	    private DailyCheck replayOrConflict(DailyCheck existing, String fingerprint) {
67	        if (!existing.fingerprint().equals(fingerprint)) {
68	            throw new ConflictException("相同 requestId 但业务字段不一致，拒绝重复受理: " + existing.requestId());
69	        }
70	        return existing;
