    @Test
    void dispenseWhileCandidatePendingSucceedsAndRejectsChangeOnSecondReview() {
        Fixture f = newCheckedFixture();
        DoseChangeOrder order = doseChangeService.submit(unique("REQ-CHG"), f.dispensingId, 1, NEW_EPOCH).order();
