            doseChangeService.review(unique("REQ-REV"), order.id(), "carol");

            CountDownLatch start = new CountDownLatch(1);
            ExecutorService pool = Executors.newFixedThreadPool(2);
            try {
                Future<?> approve = pool.submit(() -> {
                    await(start);
                    doseChangeService.review(unique("REQ-REV-APPROVE"), order.id(), "dave");
                });
                Future<?> dispense = pool.submit(() -> {
                    await(start);
                    dispensingService.dispense(unique("REQ-DISP-RACE"), f.dispensingId, 0.0, ADMIN_EPOCH);
                });
